'use client'
import { cn, useControllableSignal, useSignal, useSignalEffect, useSignals } from '@cascivo/core'
import { builtin, t } from '@cascivo/i18n'
import { Children, useRef } from 'react'
import type { KeyboardEvent, ReactNode } from 'react'
import styles from './resizable.module.css'

export interface ResizableProps {
  children: ReactNode
  /**
   * Axis the panes are split along. `horizontal` puts them side by side with a handle you
   * drag left and right; `vertical` stacks them with a handle you drag up and down.
   *
   * @defaultValue `horizontal`
   * @see the component manifest
   */
  orientation?: 'horizontal' | 'vertical'
  /**
   * The initial split ratio when uncontrolled.
   *
   * @defaultValue `0.5`
   * @see the component manifest
   */
  defaultRatio?: number
  ratio?: number
  /**
   * Minimum allowed split ratio.
   *
   * @defaultValue `0.1`
   * @see the component manifest
   */
  minRatio?: number
  /**
   * Maximum allowed split ratio.
   *
   * @defaultValue `0.9`
   * @see the component manifest
   */
  maxRatio?: number
  onRatioChange?: (ratio: number) => void
  className?: string
  label?: string
  /**
   * Alias of `label` — the same invisible accessible name under the catalog's own spelling.
   *
   * `ariaLabel` is what the catalog calls a name nothing paints, so it is the guess an agent
   * makes after reading one other component (2026-08-21 report item 1). This component
   * predates the convention and shipped `label`; both work and neither is deprecated.
   */
  ariaLabel?: string
}

function clamp(n: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, n))
}

export function Resizable({
  children,
  orientation = 'horizontal',
  defaultRatio = 0.5,
  ratio,
  minRatio = 0.1,
  maxRatio = 0.9,
  onRatioChange,
  className,
  label,
  ariaLabel,
}: ResizableProps) {
  useSignals()
  const panes = Children.toArray(children)
  const [first, second] = panes

  const [value, setValue] = useControllableSignal<number>({
    value: ratio,
    defaultValue: defaultRatio,
    onChange: onRatioChange,
  })

  const rootRef = useRef<HTMLDivElement>(null)
  const dragging = useSignal(false)

  const set = (next: number): void => {
    setValue(clamp(next, minRatio, maxRatio))
  }

  const ratioFromPointer = (clientX: number, clientY: number): number => {
    const el = rootRef.current
    if (!el) return value.value
    const rect = el.getBoundingClientRect()
    return orientation === 'horizontal'
      ? (clientX - rect.left) / rect.width
      : (clientY - rect.top) / rect.height
  }

  useSignalEffect(() => {
    if (!dragging.value) return
    const onMove = (e: PointerEvent): void => set(ratioFromPointer(e.clientX, e.clientY))
    const onUp = (): void => {
      dragging.value = false
    }
    window.addEventListener('pointermove', onMove)
    window.addEventListener('pointerup', onUp)
    return () => {
      window.removeEventListener('pointermove', onMove)
      window.removeEventListener('pointerup', onUp)
    }
  })

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>): void => {
    const step = e.shiftKey ? 0.1 : 0.02
    const decKey = orientation === 'horizontal' ? 'ArrowLeft' : 'ArrowUp'
    const incKey = orientation === 'horizontal' ? 'ArrowRight' : 'ArrowDown'
    if (e.key === decKey) set(value.value - step)
    else if (e.key === incKey) set(value.value + step)
    else if (e.key === 'Home') set(minRatio)
    else if (e.key === 'End') set(maxRatio)
    else return
    e.preventDefault()
  }

  const handleLabel = ariaLabel ?? label ?? t(builtin.resizable.handle)
  const pct = Math.round(value.value * 100)

  return (
    <div
      ref={rootRef}
      className={cn(styles['resizable'], className)}
      data-orientation={orientation}
      style={{ '--cascivo-resizable-ratio': value.value } as Record<string, string | number>}
    >
      <div className={styles['pane']}>{first}</div>

      <div
        className={styles['handle']}
        role="separator"
        aria-orientation={orientation}
        aria-label={handleLabel}
        aria-valuenow={pct}
        aria-valuemin={Math.round(minRatio * 100)}
        aria-valuemax={Math.round(maxRatio * 100)}
        tabIndex={0}
        onKeyDown={onKeyDown}
        onPointerDown={(e) => {
          e.preventDefault()
          dragging.value = true
        }}
      >
        <span className={styles['grip']} aria-hidden="true" />
      </div>

      <div className={styles['pane']}>{second}</div>
    </div>
  )
}

@layer cascivo.component {
  .resizable {
    display: flex;
    inline-size: 100%;
    block-size: 100%;
    overflow: hidden;

    &[data-orientation='horizontal'] {
      flex-direction: row;
    }

    &[data-orientation='vertical'] {
      flex-direction: column;
    }
  }

  .pane {
    overflow: auto;
    min-inline-size: 0;
    min-block-size: 0;

    &:first-child {
      flex: var(--cascivo-resizable-ratio, 0.5);
    }

    &:last-child {
      flex: calc(1 - var(--cascivo-resizable-ratio, 0.5));
    }
  }

  .handle {
    position: relative;
    flex: 0 0 auto;
    display: flex;
    align-items: center;
    justify-content: center;
    background-color: var(--cascivo-color-border);
    touch-action: none;

    &:hover {
      background-color: var(--cascivo-color-border-strong);
    }

    &:focus-visible {
      outline: none;
      box-shadow: var(--cascivo-focus-ring);
    }
  }

  .grip {
    border-radius: var(--cascivo-radius-full);
    background-color: var(--cascivo-color-border-strong);
  }

  .resizable[data-orientation='horizontal'] .handle {
    inline-size: 0.5rem;
    cursor: col-resize;
  }

  .resizable[data-orientation='horizontal'] .grip {
    inline-size: 0.125rem;
    block-size: 2rem;
  }

  .resizable[data-orientation='vertical'] .handle {
    block-size: 0.5rem;
    cursor: row-resize;
  }

  .resizable[data-orientation='vertical'] .grip {
    block-size: 0.125rem;
    inline-size: 2rem;
  }
}

@media (forced-colors: active) {
  .handle {
    border: 1px solid ButtonText;
  }

  .handle:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: 2px;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'Resizable',
  description:
    'Two-pane splitter whose divider can be dragged or keyboard-nudged to reallocate space',
  category: 'layout',
  // Reallocating space by drag or keyboard is the component.
  clientJs: 'required',
  states: [],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'ariaLabel',
      nameVisibility: 'invisible',
      description:
        'Alias of `label` — the same invisible accessible name under the catalog spelling. Neither is deprecated.',
      type: 'string',
      required: false,
    },
    {
      name: 'label',
      nameVisibility: 'invisible',
      type: 'string',
      required: false,
      description: 'Accessible label for the resize handle.',
    },
    { name: 'children', type: 'ReactNode', required: true, description: 'Exactly two panes' },
    {
      name: 'orientation',
      description:
        'Axis the panes are split along. `horizontal` puts them side by side with a handle you drag left and right; `vertical` stacks them with a handle you drag up and down.',
      type: "'horizontal' | 'vertical'",
      required: false,
      default: 'horizontal',
    },
    {
      name: 'defaultRatio',
      description: 'The initial split ratio when uncontrolled.',
      type: 'number',
      required: false,
      default: '0.5',
    },
    { name: 'ratio', type: 'number', required: false, description: 'Controlled ratio (0–1)' },
    {
      name: 'minRatio',
      description: 'Minimum allowed split ratio.',
      type: 'number',
      required: false,
      default: '0.1',
    },
    {
      name: 'maxRatio',
      description: 'Maximum allowed split ratio.',
      type: 'number',
      required: false,
      default: '0.9',
    },
    {
      name: 'onRatioChange',
      description: 'Called with the new split ratio when it changes.',
      type: '(ratio: number) => void',
      required: false,
    },
  ],
  tokens: [
    '--cascivo-color-border',
    '--cascivo-color-border-strong',
    '--cascivo-radius-full',
    '--cascivo-focus-ring',
  ],
  accessibility: {
    role: 'separator',
    wcag: '2.2-AA',
    keyboard: ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End'],
    apgPattern: 'windowsplitter',
    forcedColors: true,
  },
  examples: [
    {
      title: 'Horizontal split',
      code: '<Resizable>\n  <Editor />\n  <Preview />\n</Resizable>',
    },
    {
      title: 'Vertical with bounds',
      code: '<Resizable orientation="vertical" defaultRatio={0.3} minRatio={0.2} maxRatio={0.8}>\n  <Toolbar />\n  <Canvas />\n</Resizable>',
    },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  tags: ['splitter', 'panes', 'layout', 'resize', 'divider'],
  intent: {
    whenToUse: [
      'Letting users reallocate space between two adjacent regions, e.g. an editor and a preview',
      'Side panels or inspectors whose width the user should control',
      'Master/detail layouts where one pane may need more room than the default',
    ],
    whenNotToUse: [
      'Fixed layouts where the split should never change — use plain flex/grid',
      'More than two siblings need independent resizing — compose nested splitters instead',
    ],
    antiPatterns: [
      {
        bad: '<Resizable> wrapping three panes',
        good: 'Nest two Resizable splitters so each divider controls exactly one boundary',
        why: 'A single separator can only mediate one boundary between two panes',
      },
    ],
    related: [
      {
        name: 'Slider',
        relationship: 'alternative',
        reason: 'Use a slider when picking a value, not when allocating layout space',
      },
    ],
    a11yRationale:
      'The divider is a focusable role="separator" with aria-orientation and aria-valuenow/min/max reflecting the percentage split; arrow keys nudge the ratio and Home/End snap to the configured bounds, matching the APG window-splitter pattern.',
    flexibility: [
      {
        area: 'sizing',
        level: 'strict',
        note: 'Pane sizes derive from a single --cascivo-resizable-ratio custom property via flex',
      },
      { area: 'min/max ratio', level: 'flexible', note: 'Consumer-defined clamp range' },
    ],
  },
}
